import six
import time
import re
import logging
from abc import ABCMeta, abstractmethod
from taf.transport.ssh import ssh
from taf.internal.managedobject import ManagedObject
from .exceptions import ExecutorInputInvalid
from .factory import BaseFactory


@six.add_metaclass(ABCMeta)
class Executor(ManagedObject):
    """Abstract base validator class."""

    def __init__(self, config, *args, **kwargs):
        super(Executor, self).__init__(**kwargs)
        self._config = config
        self._end_flag = 'execute_command_finished'
        self._end_reg = r'\r?\n((?!echo).)*' + self._end_flag + r'\r?\n'
        self._command_connector = ' ; '

    @abstractmethod
    def _connect_to(self, ip, username, password=None, port=None, **kwargs):
        """Abstract method to connect to ip.
         have to implement this method.
        """

    @abstractmethod
    def execute(self, command, expect_regex='', timeout=30, **kwargs):
        """Abstract method to execute command.
         have to implement this method.
        """

    def _get_output_without_flag(self, output='', command=''):
        if ('echo ' + self._end_flag) in output:
            output = output.split(self._end_flag)[1].strip()
        elif command in output:
            output = output[output.find(command) + len(command):]
        return output

    def _check_end_flag(self, content='', expect_reg='', command=''):
        if ('echo ' + self._end_flag) in command:
            return re.search(self._end_reg, content)
        else:
            content = self._get_output_without_flag(content, command)
            return re.search(expect_reg, content)

    @abstractmethod
    def _disconnect(self, **kwargs):
        """Abstract method to disconnect with connection.
         have to implement this method.
        """

    def _setup(self):
        self._connect_to(ip=self._config.addr,
                         username=self._config.username,
                         password=self._config.password,
                         port=self._config.port,
                         proxy=self._config.proxy)
        logging.info(f'{self._config.addr} has been connected')

    def _teardown(self):
        self._disconnect()
        logging.info(f'{self._config.addr} has been disconnected')


class SshExecutor(Executor):

    def __init__(self, config, **kwargs):
        super().__init__(config, **kwargs)
        self.ssh = ssh()
        self.alias = int(time.time() * 1000)
        self._proxy_alias = None
        self.persist_channel = None
        self.persist_flag = '^'

    def is_run_on_persist_channel(self, command):
        return command.startswith(self.persist_flag)

    def upload_file(self, local_path, remote_path):
        self.ssh.upload_file(local_path=local_path, remote_path=remote_path, connection=self.alias)

    def download_file(self, remote_path, local_path):
        self.ssh.download_file(remote_path=remote_path, local_path=local_path, connection=self.alias)

    def _connect_to(self, ip, username, password=None, port=None, proxy=None):
        """
        connect to ip with name and password, port
        """
        if not ip or not username:
            raise ExecutorInputInvalid

        if proxy:
            self._connect_to_proxy(proxy)

        self.ssh.connect_to(hostname=ip,
                            username=str(username),
                            password=str(password),
                            port=port,
                            proxy=self._proxy_alias,
                            alias=self.alias)

    def _connect_to_proxy(self, proxy_config):
        self._proxy_alias = f"{proxy_config.addr}_{proxy_config.username}_{time.time()}"

        self.ssh.connect_to(hostname=proxy_config.addr,
                            username=proxy_config.username,
                            password=proxy_config.password,
                            port=proxy_config.port,
                            alias=self._proxy_alias)

    def _disconnect(self, connection=None):
        """
        disconnect with ssh
        """
        try:
            self.persist_channel = None
            self.ssh.disconnect(self.alias)
        except BaseException:
            pass

    def execute(self, command, expect_regex='', timeout=30, **kwargs):  # noqa: C901
        """
        execute command through ssh
        :return str : output after command execute
        """
        logging.info(f"input command {command}, "
                     f"regex is {expect_regex}"
                     f"timeout is {timeout}")

        if not command:
            raise ExecutorInputInvalid

        persisted = self.is_run_on_persist_channel(command)

        stripped_command = command.strip(self.persist_flag).strip()
        is_run_in_background = stripped_command.endswith('&')
        if expect_regex == '' and not is_run_in_background and not persisted:
            command = stripped_command + self._command_connector + 'echo ' + self._end_flag
        else:
            command = stripped_command

        if not persisted:
            chanel = self.ssh.get_connection_by_alias(self.alias).invoke_shell()
        elif not self.persist_channel:
            chanel = self.ssh.get_connection_by_alias(self.alias).invoke_shell()
            self.persist_channel = chanel
        else:
            chanel = self.persist_channel

        time.sleep(1)

        logging.info(f"finally execute command {command}")
        chanel.send(command + '\n')

        # this sleep is required, otherwise the command will not be executed
        # because of the chanel close later
        time.sleep(2)

        start = time.time()
        if persisted:
            return (False, '')

        if is_run_in_background:
            chanel.close()
            return (False, '')

        result = self._read_until_end(chanel, command, start, str(expect_regex), timeout)
        chanel.close()
        return result

    @staticmethod
    def _get_output_by_expect(output='', expect_regex=''):
        if output != '' and expect_regex != '':
            if re.search(expect_regex, output):
                end_index_list = [m.end() for m in re.finditer(expect_regex, output)]
                output = output[0:end_index_list[0]]
            else:
                output = ''

        return output

    def read_persist_channel(self, expect_regex='', timeout=30):
        start = time.time()
        return self._read_until_end(self.persist_channel, '', start, expect_regex, timeout)

    def _read_until_end(self, chanel, command, start, expect_regex='', timeout=30):
        output = ''
        nbytes = 65535
        time_interval = 0.1

        is_timeout = True

        while (time.time() - float(start)) < timeout:
            if self._check_end_flag(output, expect_regex, command):
                is_timeout = False
                break
            if chanel.recv_ready():
                message = chanel.recv(nbytes)
                if isinstance(message, bytes):
                    message = message.decode()
                output += message
            time.sleep(time_interval)

        output = self._get_output_without_flag(output, command)
        if not is_timeout:
            output = self._get_output_by_expect(output, expect_regex)

        return is_timeout, output.replace("\\r", "").replace("\\n", "").strip()


class SshExecutorFactory(BaseFactory):

    def __init__(self):
        BaseFactory.__init__(self)

    def create(self, config):
        return SshExecutor(config)
